graphql.query:
query listQuotes($customerIdFilter: String!, $dateFromFilter: String!, $dateToFilter: String!, $offset: Int, $limit: Int, $filter: String!) {
  listQuotes @filter(filters: [$customerIdFilter, $dateFromFilter, $dateToFilter, $filter, "", ""]) @limit(offset: $offset, limit: $limit) {
    ...ListQuoteFragment
    __typename
  }
}

fragment ListQuoteFragment on Quote {
  id
  name
  state
  number
  initialBaselineQuoteId
  baselineQuoteId
  revision
  quoteDate
  businessAction
  extendedParameters
  validFor {
    endDateTime
    startDateTime
    __typename
  }
  quoteTotalPrice {
    priceType
    priceCurrency
    price {
      valueIncludingTaxRounded
      __typename
    }
    recurringChargePeriod
    __typename
  }
  quoteItem {
    id
    businessGroupId
    rootQuoteItemId
    parentQuoteItemId
    action
    extendedParameters
    businessAction
    cpiBillingAccountId
    quoteItemPrice {
      priceType
      price {
        valueIncludingTaxRounded
        approxInstallmentPaymentAmountIncludingTaxRounded
        __typename
      }
      priceCurrency
      __typename
    }
    product {
      productCharacteristic {
        rawValue
        value
        businessType
        name
        __typename
      }
      __typename
    }
    numberOfInstallments
    productOffering {
      id
      name
      origin {
        isTangible
        id
        name
        localizedData {
          locale
          name
          __typename
        }
        category {
          id
          __typename
        }
        productFamily {
          id
          __typename
        }
        enrichmentContainer {
          staticEnrichment {
            ...StaticEnrichmentValueFragment
            __typename
          }
          ...EnrichmentContainerFragment
          __typename
        }
        __typename
      }
      __typename
    }
    billingAccount {
      id
      __typename
    }
    __typename
  }
  contactMedium {
    ...ContactMediumFragment
    __typename
  }
  relatedParty {
    ...RelatedPartyRefFragment
    __typename
  }
  __typename
}

fragment StaticEnrichmentValueFragment on StaticEnrichmentValue {
  name
  atType
  value
  localizedGroup {
    ...LocalizedDataParts
    __typename
  }
  localizedName {
    ...LocalizedDataParts
    __typename
  }
  localizedValue {
    ...LocalizedDataParts
    __typename
  }
  group
  __typename
}

fragment LocalizedDataParts on LocalizedData {
  name
  description
  locale
  __typename
}

fragment EnrichmentContainerFragment on EnrichmentContainer {
  id
  name
  entity {
    id
    name
    __typename
  }
  validFor {
    startDateTime
    endDateTime
    __typename
  }
  wrapper {
    name
    enrichment {
      name
      attribute {
        meta
        name
        value
        localizedName {
          ...LocalizedDataParts
          __typename
        }
        localizedValue {
          ...LocalizedDataParts
          __typename
        }
        __typename
      }
      component {
        name
        order
        attribute {
          meta
          name
          value
          localizedName {
            ...LocalizedDataParts
            __typename
          }
          localizedValue {
            ...LocalizedDataParts
            __typename
          }
          __typename
        }
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}

fragment ContactMediumFragment on ContactMedium {
  id
  type
  mediumType
  preferred
  characteristic {
    emailAddress
    phoneNumber
    country
    postCode
    stateOrProvince
    city
    street1
    street2
    type
    extendedAttributes
    extendedParameters
    __typename
  }
  __typename
}

fragment RelatedPartyRefFragment on RelatedPartyRef {
  atReferredType
  role
  id
  name
  userOfService
  origin {
    ... on Customer {
      id
      name
      contactMedium {
        ...ContactMediumFragment
        __typename
      }
      __typename
    }
    __typename
  }
  __typename
}
